css:
@media print {
    body { margin: 0; padding: 20px; }
}

.pdc-receipt-voucher {
    font-family: Arial, sans-serif;
    max-width: 210mm;
    margin: 0 auto;
    padding: 20px;
    font-size: 10pt;
}

.voucher-title {
    text-align: center;
    font-size: 14pt;
    font-weight: bold;
    letter-spacing: 2px;
    text-decoration: underline;
    margin-bottom: 25px;
}

.header-section {
    margin-bottom: 20px;
}

.header-row {
    display: flex;
    justify-content: space-between;
    margin-bottom: 10px;
    font-size: 10pt;
}

.header-left {
    flex: 1;
}

.header-center {
    flex: 1;
    text-align: center;
    font-weight: bold;
}

.header-right {
    flex: 1;
    text-align: right;
}

.field-label {
    font-weight: bold;
    display: inline-block;
    min-width: 90px;
}

.cheque-row {
    margin: 15px 0;
    padding: 10px 0;
}

.details-section {
    margin: 20px 0;
}

.details-table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    font-size: 10pt;
}

.details-table th {
    background-color: #f5f5f5;
    border: 1px solid #000;
    padding: 8px;
    text-align: left;
    font-weight: bold;
}

.details-table td {
    border: 1px solid #000;
    padding: 8px;
}

.amount-right {
    text-align: right;
}

.total-row {
    border-top: 2px solid #000;
    font-weight: bold;
}

.amount-words {
    margin: 15px 0;
    padding: 8px 0;
    text-transform: uppercase;
    font-weight: bold;
    font-size: 10pt;
}

.signature-section {
    display: flex;
    justify-content: space-between;
    /*margin-top: 80px;*/
    /*padding-top: 20px;*/
}

.signature-box {
    flex: 1;
    text-align: center;
    font-weight: bold;
}

.signature-line {
    border-top: 1px solid #000;
    margin-top: 60px;
    padding-top: 5px;
}

.no-border {
    border: none !important;
}
